// Format hasil LENSA ke response JSON untuk web app
const d = $input.item.json?.data ?? [];
const msg = $input.item.json?.message ?? '';
const kes = $input.item.json?.kesimpulan ?? '';

function raw(i) { return d?.[i]?.value ?? ''; }
function stripUnit(v) { return String(v ?? '').replace(/dBm/gi, '').trim(); }

const onuStatusRaw = raw(9);
const onuRxRaw     = raw(19);
const oltRxRaw     = raw(22);
const onuSn        = raw(8);
const acsRaw       = raw(32);
const pcrf         = raw(34);
const gpon         = raw(0);

// Tentukan emoji/status
function rxEmoji(v) {
  const n = parseFloat(stripUnit(v));
  if (isNaN(n)) return 'error';
  if (n < -60 || n > 0) return 'error';
  if (n < -24) return 'warn';
  return 'ok';
}

// Bangun result_text (HTML) untuk kompatibilitas dengan bot lama
const EO = '\u2705', EW = '\u26a0\ufe0f', EB = '\u274c';
const onuEmoji  = onuStatusRaw.toUpperCase().includes('ONLINE') ? EO : (onuStatusRaw.toUpperCase().includes('LOS') ? EB : EW);
const onuRxEmoji = rxEmoji(onuRxRaw) === 'ok' ? EO : (rxEmoji(onuRxRaw) === 'warn' ? EW : EB);
const oltRxEmoji = rxEmoji(oltRxRaw) === 'ok' ? EO : (rxEmoji(oltRxRaw) === 'warn' ? EW : EB);

const result_text = `<b>ONU status:</b> ${onuStatusRaw} ${onuEmoji}\n<b>ONU rx:</b> ${stripUnit(onuRxRaw)} dBm ${onuRxEmoji}\n<b>OLT rx:</b> ${stripUnit(oltRxRaw)} dBm ${oltRxEmoji}\n<b>SN ONT:</b> <code>${onuSn}</code>\n<b>ACS:</b> ${acsRaw}\n<b>PCRF:</b> ${pcrf}\n<b>GPON:</b> ${gpon}\n\n<b>${kes}</b>`;

return [{ json: {
  success:     true,
  onu_sn:      onuSn,
  onu_status:  onuStatusRaw,
  onu_rx:      stripUnit(onuRxRaw),
  olt_rx:      stripUnit(oltRxRaw),
  onu_rx_status: rxEmoji(onuRxRaw),
  olt_rx_status: rxEmoji(oltRxRaw),
  acs_status:  acsRaw,
  pcrf:        pcrf,
  gpon:        gpon,
  kesimpulan:  kes,
  message:     msg,
  result_text
}}];

return [{ json: {
  success:    false,
  error:      'ibooster_error',
  message:    $input.item.json?.message ?? 'Server LENSA error'
}}];
